# PATCH_V8_PAPER_METRICS_BEGIN
try{

$metrics="C:\alpaca-bot\ORG_BOT_UNIFIED\runtime\paper\logs\paper_runtime_metrics.jsonl"
$dir=Split-Path $metrics
New-Item -ItemType Directory -Force $dir|Out-Null

$run_id=[guid]::NewGuid().ToString()

$row=[ordered]@{
kind="paper_runtime_metrics_v8"
run_id=$run_id
pid=$PID
ts=(Get-Date).ToString("s")
profile=$env:TBOT_PROFILE
wrapper="ORG_UNIFIED_RUNTIME_MANAGER.ps1"
}

($row|ConvertTo-Json -Compress)|Add-Content $metrics -Encoding UTF8

}catch{
Write-Host "Paper metrics instrumentation failed"
}
# PATCH_V8_PAPER_METRICS_END
